1	import { describe, expect, it } from "vitest";
2	import request from "supertest";
3	import { app } from "../src/server.js";
4	import { queryNotes } from "../src/store/notesStore.js";
5	
6	async function createNote(title: string, body: string, tags?: unknown) {
7	  const payload: { title: string; body: string; tags?: unknown } = { title, body };
8	  if (tags !== undefined) {
9	    payload.tags = tags;
10	  }
11	  return request(app).post("/notes").send(payload);
12	}
13	
14	describe("Notes API", () => {
15	  it("creates and lists a note in the pagination envelope", async () => {
16	    const created = await createNote("Buy milk", "2%, from the corner store");
17	
18	    expect(created.status).toBe(201);
19	    expect(created.body.title).toBe("Buy milk");
20	    expect(created.body.tags).toEqual([]);
21	
22	    const listed = await request(app).get("/notes");
23	    expect(listed.status).toBe(200);
24	    expect(listed.body.items.some((note: { id: string }) => note.id === created.body.id)).toBe(
25	      true,
26	    );
27	    expect(listed.body.page).toBe(1);
28	    expect(listed.body.pageSize).toBe(20);
29	  });
30	
31	  it("normalizes tags and enforces tag input validation", async () => {
32	    const created = await createNote("Tagged", "body", [" Work ", "work", "Home"]);
33	    expect(created.status).toBe(201);
34	    expect(created.body.tags).toEqual(["work", "home"]);
35	
36	    for (const tags of [null, ["ok", ""], "work"]) {
37	      const response = await createNote("Invalid tags", "body", tags);
38	      expect(response.status).toBe(400);
39	    }
40	  });
41	
42	  it("enforces tag count and Unicode length limits before deduplication", async () => {
43	    const valid = await createNote("Limits", "body", [
44	      ...Array.from({ length: 19 }, (_, index) => `tag-${index}`),
45	      "😀".repeat(32),
46	    ]);
47	    expect(valid.status).toBe(201);
48	
49	    const tooLong = await createNote("Too long", "body", ["😀".repeat(33)]);
50	    expect(tooLong.status).toBe(400);
51	
52	    const tooMany = await createNote(
53	      "Too many",
54	      "body",
55	      Array.from({ length: 21 }, () => "duplicate"),
56	    );
57	    expect(tooMany.status).toBe(400);
58	  });
59	
60	  it("updates tags without changing other fields and supports clearing them", async () => {
61	    const created = await createNote("Original title", "Original body", ["old"]);
62	    const updated = await request(app)
63	      .patch(`/notes/${created.body.id}`)
64	      .send({ tags: [" New ", "new"] });
65	
66	    expect(updated.status).toBe(200);
67	    expect(updated.body.title).toBe("Original title");
68	    expect(updated.body.body).toBe("Original body");
69	    expect(updated.body.tags).toEqual(["new"]);
70	
71	    const noOp = await request(app).patch(`/notes/${created.body.id}`).send({});
72	    expect(noOp.status).toBe(200);
73	    expect(noOp.body).toEqual(updated.body);
74	
75	    const cleared = await request(app).patch(`/notes/${created.body.id}`).send({ tags: [] });
76	    expect(cleared.status).toBe(200);
77	    expect(cleared.body.tags).toEqual([]);
78	
79	    const invalid = await request(app).patch(`/notes/${created.body.id}`).send({ tags: null });
80	    expect(invalid.status).toBe(400);
81	
82	    const missing = await request(app).patch("/notes/does-not-exist").send({});
83	    expect(missing.status).toBe(404);
84	  });
85	
86	  it("validates PATCH bodies before looking up the note", async () => {
87	    for (const body of ["null", "[]", '"invalid"']) {
88	      const response = await request(app)
89	        .patch("/notes/does-not-exist")
90	        .set("Content-Type", "application/json")
91	        .send(body);
92	      expect(response.status).toBe(400);
93	      expect(response.body.error).toBe("request body must be an object");
94	    }
95	
96	    const malformed = await request(app)
97	      .patch("/notes/does-not-exist")
98	      .send({ title: 123 });
99	    expect(malformed.status).toBe(400);
100	    expect(malformed.body.error).toBe("title and body must be strings");
101	  });
102	
103	  it("filters tags case-insensitively and rejects invalid tag filters", async () => {
104	    const created = await createNote("Filter target", "body", ["Work"]);
105	    await createNote("Other filter note", "body", ["personal"]);
106	
107	    const filtered = await request(app).get("/notes").query({ tag: "WoRk" });
108	    expect(filtered.status).toBe(200);
109	    expect(filtered.body.items.map((note: { id: string }) => note.id)).toContain(created.body.id);
110	
111	    for (const tag of ["", "   "]) {
112	      const invalid = await request(app).get("/notes").query({ tag });
113	      expect(invalid.status).toBe(400);
114	      expect(invalid.body.error).toBe("tag must be a non-empty string of at most 32 characters");
115	    }
116	  });
117	
118	  it("searches title and body with Unicode-aware case normalization", async () => {
