import { describe, expect, it, beforeEach, vi } from "vitest";
import request from "supertest";
import express from "express";
import { rateLimiter, resetBucketsForTesting } from "../src/middleware/rateLimiter.js";

describe("Rate Limiter", () => {
  beforeEach(() => {
    resetBucketsForTesting();
    vi.useFakeTimers();
  });

  function createTestApp(maxRequests: number = 5, windowMs: number = 60000) {
    const app = express();
    app.use(rateLimiter({ maxRequests, windowMs, burstCapacity: 2 }));
    app.get("/test", (_req, res) => res.json({ ok: true }));
    return app;
  }

  it("allows requests within the limit", async () => {
    const app = createTestApp(5);

    for (let i = 0; i < 5; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
      expect(res.body).toEqual({ ok: true });
    }
  });

  it("returns 429 when limit is exceeded", async () => {
    const app = createTestApp(3);

    for (let i = 0; i < 3; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
    }

    const rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);
    expect(rateLimited.body).toHaveProperty("error", "Rate limit exceeded");
  });

  it("includes Retry-After header on rate limit", async () => {
    const app = createTestApp(2);

    await request(app).get("/test");
    await request(app).get("/test");

    const rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);
    expect(rateLimited.headers["retry-after"]).toBeDefined();
    expect(parseInt(rateLimited.headers["retry-after"])).toBeGreaterThan(0);
  });

  it("refills tokens over time within the window", async () => {
    const app = createTestApp(10, 60000);

    for (let i = 0; i < 10; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
    }

    let rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);

    vi.advanceTimersByTime(6000);

    const afterRefill = await request(app).get("/test");
    expect(afterRefill.status).toBe(200);
  });

  it("respects burst capacity while maintaining average rate", async () => {
    const app = createTestApp(3, 60000);

    for (let i = 0; i < 2; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
    }

    const rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);

    vi.advanceTimersByTime(20000);

    const afterRefill = await request(app).get("/test");
    expect(afterRefill.status).toBe(200);
  });

  it("tracks separate limits for different IPs", async () => {
    const app = createTestApp(2);

    const res1 = await request(app).get("/test");
    const res2 = await request(app).get("/test");
    expect(res1.status).toBe(200);
    expect(res2.status).toBe(200);

    const res3 = await request(app).get("/test");
    expect(res3.status).toBe(429);

    const res4 = request(app).get("/test").set("X-Forwarded-For", "192.168.1.2");
    expect((await res4).status).toBe(200);
  });
});

import { describe, expect, it, beforeEach, vi } from "vitest";
import request from "supertest";
import express from "express";
import { rateLimiter, resetBucketsForTesting } from "../src/middleware/rateLimiter.js";

describe("Rate Limiter", () => {
  beforeEach(() => {
    resetBucketsForTesting();
    vi.useFakeTimers();
  });

  function createTestApp(maxRequests: number = 5, windowMs: number = 60000) {
    const app = express();
    app.use(rateLimiter({ maxRequests, windowMs, burstCapacity: 2 }));
    app.get("/test", (_req, res) => res.json({ ok: true }));
    return app;
  }

  it("allows requests within the limit", async () => {
    const app = createTestApp(5);

    for (let i = 0; i < 5; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
      expect(res.body).toEqual({ ok: true });
    }
  });

  it("returns 429 when limit is exceeded", async () => {
    const app = createTestApp(3);

    for (let i = 0; i < 3; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
    }

    const rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);
    expect(rateLimited.body).toHaveProperty("error", "Rate limit exceeded");
  });

  it("includes Retry-After header on rate limit", async () => {
    const app = createTestApp(2);

    await request(app).get("/test");
    await request(app).get("/test");

    const rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);
    expect(rateLimited.headers["retry-after"]).toBeDefined();
    expect(parseInt(rateLimited.headers["retry-after"])).toBeGreaterThan(0);
  });

  it("refills tokens over time within the window", async () => {
    const app = createTestApp(10, 60000);

    for (let i = 0; i < 10; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
    }

    let rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);

    vi.advanceTimersByTime(6000);

    const afterRefill = await request(app).get("/test");
    expect(afterRefill.status).toBe(200);
  });

  it("respects burst capacity while maintaining average rate", async () => {
    const app = createTestApp(3, 60000);

    for (let i = 0; i < 2; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
    }

    const rateLimited = await request(app).get("/test");
    expect(rateLimited.status).toBe(429);

    vi.advanceTimersByTime(20000);

    const afterRefill = await request(app).get("/test");
    expect(afterRefill.status).toBe(200);
  });

  it("tracks separate limits for different IPs", async () => {
    const app = createTestApp(2);

    const res1 = await request(app).get("/test");
    const res2 = await request(app).get("/test");
    expect(res1.status).toBe(200);
    expect(res2.status).toBe(200);

    const res3 = await request(app).get("/test");
    expect(res3.status).toBe(429);

    const res4 = request(app).get("/test").set("X-Forwarded-For", "192.168.1.2");
    expect((await res4).status).toBe(200);
  });
});

