+import { type Request, type Response, type NextFunction } from "express";
+
+interface TokenBucket {
+  tokens: number;
+  lastRefillTime: number;
+}
+
+interface RateLimiterOptions {
+  maxRequests?: number;
+  windowMs?: number;
+  burstCapacity?: number;
+}
+
+const buckets = new Map<string, TokenBucket>();
+
+const CLEANUP_INTERVAL = 60000; // 1 minute
+const CLEANUP_AGE = 300000; // 5 minutes
+
+function cleanupOldBuckets() {
+  const now = Date.now();
+  for (const [ip, bucket] of buckets.entries()) {
+    if (now - bucket.lastRefillTime > CLEANUP_AGE) {
+      buckets.delete(ip);
+    }
+  }
+}
+
+const cleanupTimer = setInterval(cleanupOldBuckets, CLEANUP_INTERVAL);
+cleanupTimer.unref?.();
+
+export function rateLimiter(options: RateLimiterOptions = {}) {
+  const maxRequests = options.maxRequests ?? 100;
+  const windowMs = options.windowMs ?? 60000;
+  const burstCapacity = options.burstCapacity ?? 10;
+  const refillRate = maxRequests / (windowMs / 1000);
+
+  return (req: Request, res: Response, next: NextFunction) => {
+    const clientIp = req.ip || "unknown";
+    const now = Date.now();
+
+    let bucket = buckets.get(clientIp);
+    if (!bucket) {
+      bucket = { tokens: burstCapacity, lastRefillTime: now };
+      buckets.set(clientIp, bucket);
+    }
+
+    const timePassed = (now - bucket.lastRefillTime) / 1000;
+    const tokensToAdd = timePassed * refillRate;
+    bucket.tokens = Math.min(burstCapacity, bucket.tokens + tokensToAdd);
+    bucket.lastRefillTime = now;
+
+    if (bucket.tokens >= 1) {
+      bucket.tokens -= 1;
+      next();
+    } else {
+      const secondsUntilRefill = (1 - bucket.tokens) / refillRate;
+      res.status(429).set("Retry-After", Math.ceil(secondsUntilRefill).toString()).json({
+        error: "Rate limit exceeded",
+        retryAfter: Math.ceil(secondsUntilRefill),
+      });
+    }
+  };
+}
+
+export function resetBucketsForTesting() {
+  buckets.clear();
+}
